# frozen_string_literal: true

module A2A
  module Schema
    # Artifact generated by agents
    class Artifact < SchemaObject
      attr_accessor :name, :description, :parts, :metadata,
                    :index, :append, :last_chunk

      # @param parts [Array<Part>] Artifact parts
      # @param name [String, nil] Optional name
      # @param description [String, nil] Optional description
      # @param metadata [Hash, nil] Optional metadata
      # @param index [Integer, nil] Optional index for ordering
      # @param append [Boolean, nil] Whether to append to existing artifact
      # @param last_chunk [Boolean, nil] Whether this is the last chunk
      def initialize(parts:, name: nil, description: nil, metadata: nil, index: nil, append: nil, last_chunk: nil)
        @name = name
        @description = description
        @parts = parts
        @metadata = metadata
        @index = index
        @append = append
        @last_chunk = last_chunk
      end

      REQUIRED_FIELDS = [:parts].freeze
    end
  end
end